<script setup lang="ts">
import { computed } from 'vue'
import { RouterLink } from 'vue-router'
import { Button } from '@/components/ui/button'
import type { StudentProgressResponse } from '@/lib/api'
const props=defineProps<{progress:StudentProgressResponse|null}>()
const labels:Record<string,string>={verifiedSkills:'verified skills',verifiedProjects:'verified projects',currentCertificates:'current certificates',passedAssessments:'passed assessments',cvCount:'saved CVs'}
const changes=computed(()=>{if(!props.progress?.previous)return [];return Object.entries(labels).map(([key,label])=>({label,before:props.progress!.previous![key]??0,after:props.progress!.current[key]??0})).filter(v=>v.before!==v.after)})
</script>
<template><section v-if="progress && (changes.length||progress.gaps.length)" class="grid gap-5" :class="changes.length && progress.gaps.length ? 'lg:grid-cols-2' : ''"><div v-if="changes.length" class="rounded-2xl border border-teal/30 bg-teal-soft p-6"><h2 class="font-heading text-xl text-teal">Since your last visit</h2><p class="mt-2 text-xs text-muted-foreground">{{new Date(progress.previousVisit!).toLocaleString('en-MY')}}</p><div v-for="change in changes" :key="change.label" class="mt-4 flex items-center justify-between gap-3 text-sm"><span class="capitalize">{{change.label}}</span><span class="font-semibold tabular-nums">{{change.before}} → {{change.after}}</span></div><p v-if="progress.previous?.topJobId===progress.current.topJobId && progress.current.topFit!==null && progress.previous?.topFit!==progress.current.topFit" class="mt-4 border-t border-teal/20 pt-4 text-sm">Your top role’s skills match: {{progress.previous?.topFit}} → {{progress.current.topFit}} / 100</p></div><div v-if="progress.gaps.length" class="tone-card tone-blue rounded-2xl border p-6"><h2 class="font-heading text-xl">Skills appearing in your matches</h2><p class="mt-2 text-sm leading-6 text-muted-foreground">These requirements appear in your top {{progress.comparedRoles}} roles and are not yet backed by your records.</p><ul class="mt-4 grid gap-3 sm:grid-cols-2 xl:grid-cols-3"><li v-for="gap in progress.gaps" :key="gap.skill" class="flex items-center justify-between gap-3 rounded-lg border border-primary/15 bg-card px-3 py-3 text-sm"><strong>{{gap.skill}}</strong><span class="text-xs text-muted-foreground">{{gap.roles}} role{{gap.roles===1?'':'s'}}</span></li></ul><Button as-child variant="outline" class="mt-5"><RouterLink to="/student/skills">Review my evidence</RouterLink></Button></div></section></template>
